// Horario de Brasilia (UTC-3)
const agora = new Date(Date.now() - 3 * 3600 * 1000);
const hoje = agora.toISOString().split('T')[0];

// Janela de agora ate 10 min a frente. O workflow roda a cada 5 min,
// entao qualquer reuniao e vista pelo menos uma vez antes de comecar.
// Comecar em 0 (e nao em 5) evita o buraco: uma reuniao a 3 min de
// distancia ficaria fora de uma janela 5-10 e nunca seria avisada.
// reminder_sent garante que ninguem receba o aviso duas vezes.
const ini = agora;
const fim = new Date(agora.getTime() + 10 * 60000);
const hhmm = d => d.toISOString().substring(11, 16) + ':00';

return [{ json: { data: hoje, de: hhmm(ini), ate: hhmm(fim) } }];

function render(tpl, vars) {
  return String(tpl || '').replace(/\{\{\s*(\w+)\s*\}\}/g, (m, k) =>
    k in vars ? String(vars[k]) : m
  );
}
function normalizePhone(v) {
  let d = String(v || '').replace(/\D/g, '');
  if (d.length === 12 || d.length === 13) {
    if (!d.startsWith('55')) return null;
    d = d.substring(2);
  }
  if (d.length !== 10 && d.length !== 11) return null;
  if (parseInt(d.substring(0, 2), 10) < 11) return null;
  if (d.length === 11 && d[2] !== '9') return null;
  return '55' + d;
}

const reunioes = $('Buscar Reunioes').all().map(i => i.json).filter(r => r && r.id);
if (!reunioes.length) { return []; }

const tplRow = $('Buscar Template').all().map(i => i.json).find(r => r && r.message);
const tpl = tplRow?.message
  || 'Ola *{{nome_colaborador}}*! ⏰\n\nSua reuniao comeca em breve:\n\n*Assunto:* {{titulo}}\n*Sala:* {{sala}}\n*Horario:* {{horario}}';

const out = [];
for (const b of reunioes) {
  const sala = b.rooms?.name || 'Sala';
  const data = String(b.booking_date).split('-').reverse().join('/');
  const horario = String(b.start_time).substring(0,5) + ' as ' + String(b.end_time).substring(0,5);
  for (const p of (b.booking_participants || [])) {
    const c = p.collaborators;
    if (!c) continue;
    const fone = normalizePhone(c.phone);
    if (!fone) continue;
    out.push({ json: {
      booking_id: b.id,
      number: fone,
      text: render(tpl, {
        nome_colaborador: c.name, titulo: b.title, sala, data, horario,
      }),
    }});
  }
}
return out;

// So marca reminder_sent para as reunioes cujo envio REALMENTE funcionou.
//
// O no de envio roda com continueOnFail, para que a falha de um
// participante nao derrube os demais. Antes, este passo marcava todas as
// reunioes processadas, sem olhar o resultado: um erro de rede no horario
// do lembrete marcava como avisado algo que ninguem recebeu, e o aviso se
// perdia em silencio.
//
// Agora cruzamos envio e lembrete pelo indice: o n8n preserva a ordem dos
// itens, entao o i-esimo resultado corresponde ao i-esimo lembrete.
const lembretes = $('Montar Lembretes').all();
const envios = $input.all();

const ok = new Set();
const falhou = new Set();

envios.forEach((envio, i) => {
  const bookingId = lembretes[i]?.json?.booking_id;
  if (!bookingId) return;
  // Um envio bem-sucedido traz key.id da Evolution; um erro traz .error
  const sucesso = !envio.json?.error && envio.json?.key?.id;
  (sucesso ? ok : falhou).add(bookingId);
});

// Se ao menos um participante falhou, nao marcamos a reuniao: ela volta
// no proximo ciclo e quem nao recebeu recebe. Quem ja recebeu pode levar
// a mensagem duas vezes -- preferivel a alguem perder o aviso.
const marcar = [...ok].filter(id => !falhou.has(id));

if (falhou.size) {
  console.warn('Lembretes com falha de envio, serao retentados:', [...falhou]);
}

return marcar.map(id => ({ json: { booking_id: id } }));
